import { describe, it, expect, beforeEach, vi } from "vitest";
import { createTestDb, seedBaseData } from "~/test/setup";
import * as schema from "~/db/schema";

let testDb: ReturnType<typeof createTestDb>;
let base: ReturnType<typeof seedBaseData>;

vi.mock("~/db", () => ({
  get db() {
    return testDb;
  },
}));

// Import after mock so the module picks up our test db
import {
  createNotification,
  getNotifications,
  getUnreadCount,
  markAsRead,
  markAllAsRead,
  getNotificationById,
} from "./notificationService";

function makeNotification(recipientUserId: number, overrides?: Partial<{
  title: string;
  message: string;
  linkUrl: string;
  type: schema.NotificationType;
}>) {
  return createNotification({
    recipientUserId,
    type: overrides?.type ?? schema.NotificationType.Enrollment,
    title: overrides?.title ?? "New Enrollment",
    message: overrides?.message ?? "John Doe enrolled in Test Course",
    linkUrl: overrides?.linkUrl ?? "/instructor/1/students",
  });
}

describe("notificationService", () => {
  beforeEach(() => {
    testDb = createTestDb();
    base = seedBaseData(testDb);
  });

  describe("createNotification", () => {
    it("creates a notification with all fields", () => {
      const notification = createNotification({
        recipientUserId: base.instructor.id,
        type: schema.NotificationType.Enrollment,
        title: "New Enrollment",
        message: "Jane enrolled in Test Course",
        linkUrl: `/instructor/${base.course.id}/students`,
      });

      expect(notification).toBeDefined();
      expect(notification.recipientUserId).toBe(base.instructor.id);
      expect(notification.type).toBe(schema.NotificationType.Enrollment);
      expect(notification.title).toBe("New Enrollment");
      expect(notification.message).toBe("Jane enrolled in Test Course");
      expect(notification.linkUrl).toBe(`/instructor/${base.course.id}/students`);
      expect(notification.isRead).toBe(false);
      expect(notification.createdAt).toBeDefined();
    });

    it("defaults isRead to false", () => {
      const notification = makeNotification(base.instructor.id);
      expect(notification.isRead).toBe(false);
    });
  });

  describe("getNotifications", () => {
    it("returns notifications ordered newest first", () => {
      const first = makeNotification(base.instructor.id, { message: "First" });
      const second = makeNotification(base.instructor.id, { message: "Second" });

      const result = getNotifications({ userId: base.instructor.id, limit: 10, offset: 0 });

      expect(result[0].id).toBe(second.id);
      expect(result[1].id).toBe(first.id);
    });

    it("respects limit parameter", () => {
      for (let i = 0; i < 5; i++) {
        makeNotification(base.instructor.id);
      }

      const result = getNotifications({ userId: base.instructor.id, limit: 3, offset: 0 });
      expect(result).toHaveLength(3);
    });

    it("respects offset parameter", () => {
      for (let i = 0; i < 5; i++) {
        makeNotification(base.instructor.id, { message: `Notification ${i}` });
      }

      const all = getNotifications({ userId: base.instructor.id, limit: 10, offset: 0 });
      const paged = getNotifications({ userId: base.instructor.id, limit: 10, offset: 2 });

      expect(paged).toHaveLength(3);
      expect(paged[0].id).toBe(all[2].id);
    });

    it("returns empty array when user has no notifications", () => {
      const result = getNotifications({ userId: base.instructor.id, limit: 10, offset: 0 });
      expect(result).toHaveLength(0);
    });

    it("only returns notifications for the specified user", () => {
      const otherUser = testDb
        .insert(schema.users)
        .values({ name: "Other", email: "other@example.com", role: schema.UserRole.Instructor })
        .returning()
        .get();

      makeNotification(base.instructor.id);
      makeNotification(otherUser.id);

      const result = getNotifications({ userId: base.instructor.id, limit: 10, offset: 0 });
      expect(result).toHaveLength(1);
      expect(result[0].recipientUserId).toBe(base.instructor.id);
    });
  });

  describe("getUnreadCount", () => {
    it("returns count of unread notifications", () => {
      makeNotification(base.instructor.id);
      makeNotification(base.instructor.id);
      const read = makeNotification(base.instructor.id);
      markAsRead(read.id);

      expect(getUnreadCount(base.instructor.id)).toBe(2);
    });

    it("returns 0 when all notifications are read", () => {
      const n = makeNotification(base.instructor.id);
      markAsRead(n.id);

      expect(getUnreadCount(base.instructor.id)).toBe(0);
    });

    it("returns 0 when user has no notifications", () => {
      expect(getUnreadCount(base.instructor.id)).toBe(0);
    });

    it("only counts unread for the specified user", () => {
      const otherUser = testDb
        .insert(schema.users)
        .values({ name: "Other", email: "other@example.com", role: schema.UserRole.Instructor })
        .returning()
        .get();

      makeNotification(base.instructor.id);
      makeNotification(otherUser.id);
      makeNotification(otherUser.id);

      expect(getUnreadCount(base.instructor.id)).toBe(1);
      expect(getUnreadCount(otherUser.id)).toBe(2);
    });
  });

  describe("markAsRead", () => {
    it("marks a notification as read", () => {
      const notification = makeNotification(base.instructor.id);

      const updated = markAsRead(notification.id);

      expect(updated).toBeDefined();
      expect(updated!.isRead).toBe(true);
    });

    it("does not affect other notifications", () => {
      const n1 = makeNotification(base.instructor.id);
      const n2 = makeNotification(base.instructor.id);

      markAsRead(n1.id);

      const result = getNotifications({ userId: base.instructor.id, limit: 10, offset: 0 });
      const n2Result = result.find((n) => n.id === n2.id);
      expect(n2Result!.isRead).toBe(false);
    });
  });

  describe("markAllAsRead", () => {
    it("marks all notifications as read for a user", () => {
      makeNotification(base.instructor.id);
      makeNotification(base.instructor.id);
      makeNotification(base.instructor.id);

      markAllAsRead(base.instructor.id);

      expect(getUnreadCount(base.instructor.id)).toBe(0);
    });

    it("only affects notifications for the specified user", () => {
      const otherUser = testDb
        .insert(schema.users)
        .values({ name: "Other", email: "other@example.com", role: schema.UserRole.Instructor })
        .returning()
        .get();

      makeNotification(base.instructor.id);
      makeNotification(otherUser.id);

      markAllAsRead(base.instructor.id);

      expect(getUnreadCount(base.instructor.id)).toBe(0);
      expect(getUnreadCount(otherUser.id)).toBe(1);
    });
  });

  describe("getNotificationById", () => {
    it("returns the notification when it belongs to the user", () => {
      const notification = makeNotification(base.instructor.id);

      const result = getNotificationById({
        notificationId: notification.id,
        userId: base.instructor.id,
      });

      expect(result).toBeDefined();
      expect(result!.id).toBe(notification.id);
    });

    it("returns undefined when the notification belongs to a different user", () => {
      const notification = makeNotification(base.instructor.id);

      const result = getNotificationById({
        notificationId: notification.id,
        userId: base.user.id,
      });

      expect(result).toBeUndefined();
    });

    it("returns undefined for a non-existent notification id", () => {
      const result = getNotificationById({
        notificationId: 9999,
        userId: base.instructor.id,
      });

      expect(result).toBeUndefined();
    });
  });
});

