19	export function createTestDb() {
20	  const sqlite = new Database(":memory:");
21	  sqlite.pragma("journal_mode = WAL");
22	  sqlite.pragma("foreign_keys = ON");
23	
24	  const testDb = drizzle(sqlite, { schema });
25	
26	  migrate(testDb, { migrationsFolder });
27	
28	  return testDb;
29	}
